1	-- Fix em bipar_etiqueta: no backfill, se o lote_uuid do payload nao existe em lotes,
2	-- resolve por codigo+validade via find_or_create_lote ou usa NULL.
3	-- Antes: INSERT com UUID morto -> FK rejeitava -> movimentacoes FK cascateava erro.
4	CREATE OR REPLACE FUNCTION public.bipar_etiqueta(p_uid text, p_etapa text, p_contexto jsonb DEFAULT '{}'::jsonb)
5	 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
6	AS $function$
7	DECLARE
8	  v_etiqueta public.etiquetas_qr%ROWTYPE;
9	  v_user_id uuid := auth.uid();
10	  v_user_nome text; v_status_anterior text; v_status_novo text; v_loja_id integer;
11	  v_alertas jsonb := '[]'::jsonb; v_referencia_tipo text; v_referencia_id text;
12	  v_payload jsonb; v_pid_text text; v_pid_int integer; v_lote_uuid uuid;
13	  v_produto_nome text; v_lote_codigo text; v_lote_validade date; v_qty_interna numeric;
14	BEGIN
15	  IF p_etapa NOT IN ('separacao','conferencia','entrada','saida','consumo','descarte') THEN
16	    RETURN jsonb_build_object('ok', false, 'erro', 'Etapa invalida: ' || p_etapa); END IF;
17	  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome FROM auth.users WHERE id = v_user_id;
18	  v_loja_id := NULLIF(p_contexto->>'loja_id','')::integer;
19	  v_referencia_tipo := p_contexto->>'referencia_tipo'; v_referencia_id := p_contexto->>'referencia_id';
20	  v_payload := p_contexto->'payload';
21	  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid;
22	  IF NOT FOUND THEN
23	    IF v_payload IS NULL THEN RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e sem payload para backfill'); END IF;
24	    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
